          return ERROR1;
      }
      return SUCCESS;
  }
  ```

- **Using pointers to return values**: Return the result through a pointer, which is useful when the function needs to modify a variable in the caller's scope.

  ```c
  int some_function(int *result) {
      if (/* some condition */) {
          *result = 0; // success
          return 0;
      }
      *result = -1; // failure
      return -1;
  }
  ```

- **Using error handling macros**: Define macros to handle errors in a consistent way.

  ```c
  #define HANDLE_ERROR(err) \
      do { \
          if (err) { \
              // handle error \
              return -1; \
          } \
      } while (0)

  int some_function() {
      HANDLE_ERROR(some_condition());
      HANDLE_ERROR(another_condition());
      // function logic
      return 0;
  }
  ```

Choose the method that best fits your specific needs, considering factors like the complexity of the error handling, the size of the project, and the readability of the code.

